using Acme.Data;
using Microsoft.EntityFrameworkCore;

namespace Acme.Orders;

public sealed record OrderSummary(int Id, DateTime PlacedAt, int LineCount);

public sealed class OrderQueries(ShopDbContext db)
{
    public async Task<List<OrderSummary>> ListRecentAsync(int customerId, CancellationToken ct)
    {
        var orders = await db.Orders
            .Where(o => o.CustomerId == customerId)
            .OrderByDescending(o => o.PlacedAt)
            .Take(20)
            .ToListAsync(ct);

        return orders
            .Select(o => new OrderSummary(o.Id, o.PlacedAt, o.Lines.Count))
            .ToList();
    }
}

